"""C43 exact Python source and tests, zlib/base64 packaged for source custody.

Extract with: python C43-extract-sources.py <destination-directory>.
SHA-256 for restored c43_goal_outcome.py: 46203e540b95d44c4b581da2c8bec1bc3b0e12a1bf920841bf28cbab315dd746
SHA-256 for restored test_c43_goal_outcome.py: f37f30ae0149fa536bf8cba56417bc00d576faf2b8396fa8bdca22f2e3a50ae4
The restored files are ordinary readable Python; no binaries or models are embedded.
"""
import base64, hashlib, json, pathlib, sys, zlib
PAYLOAD = ""
EXPECTED = {
    "c43_goal_outcome.py": "46203e540b95d44c4b581da2c8bec1bc3b0e12a1bf920841bf28cbab315dd746",
    "test_c43_goal_outcome.py": "f37f30ae0149fa536bf8cba56417bc00d576faf2b8396fa8bdca22f2e3a50ae4",
}
def extract(dest):
    dest = pathlib.Path(dest)
    dest.mkdir(parents=True, exist_ok=True)
    files = json.loads(zlib.decompress(base64.b64decode(PAYLOAD)))
    assert set(files) == set(EXPECTED)
    for name, content in files.items():
        data = content.encode("utf-8")
        actual = hashlib.sha256(data).hexdigest()
        if actual != EXPECTED[name]:
            raise ValueError(f"source integrity failure: {name}")
        (dest / name).write_bytes(data)
        print(f"{name}: {actual}")
if __name__ == "__main__":
    if len(sys.argv) != 2:
        raise SystemExit("usage: python C43-extract-sources.py DESTINATION")
    extract(sys.argv[1])
